/* Host test: EcuStateConfig.h generated by tools/rtegen from the test profile (section ecu_state: in
 * test_ecustate_host.py, PROFILE there) -> ecuState/EcuStateIntegration.h -> EcuStateConfig -> state machine.
 * Build and run: libs/bsw/ecuState/test/test_ecustate_host.py. */

#include "EcuStateConfig.h"
#include "ecuState/EcuStateIntegration.h"
#include "ecuState/EcuStateMachine.h"

#include <cstdio>

namespace
{
int failures = 0;
int checks   = 0;

#define CHECK(cond)                                                       \
    do                                                                    \
    {                                                                     \
        ++checks;                                                         \
        if (!(cond))                                                      \
        {                                                                 \
            ++failures;                                                   \
            std::printf("  FAIL %s:%d: %s\n", __FILE__, __LINE__, #cond); \
        }                                                                 \
    } while (false)

using namespace ::ecustate;

constexpr EcuStateConfig CONFIG = ECU_STATE_CONFIG();
static_assert(isValidEcuStateConfig(CONFIG), "test profile invalid");

void generatedValues()
{
    CHECK(CONFIG.minRunMs == 0U);
    CHECK(CONFIG.postRunMs == 750U);
    CHECK(CONFIG.shutdownTimeoutMs == 100U);        // manifest minimum
    CHECK(CONFIG.sleepTimeoutMs == 101U);           // manifest minimum = POWER_DOWN_DELAY_MS + 1
    CHECK(CONFIG.stepTimeoutMs[0] == 10U);          // nvm_timeout_ms, manifest minimum
    CHECK(CONFIG.stepTimeoutMs[1] == 20U);          // can_stop_timeout_ms
    CHECK(CONFIG.stepTimeoutMs[2] == SAFE_OUTPUTS_STEP_TIMEOUT_MS); // SYS-174: constant of the mechanism
    CHECK(CONFIG.wakeupDuringShutdown == WakeupDuringShutdown::SLEEP);
    CHECK(CONFIG.afterWatchdogReset == AfterWatchdogReset::SLEEP);
    CHECK(CONFIG.shutdownStepError == ShutdownStepError::CONTINUE);
    // SYS-02: wakeup_can CAN0 (the only bus of the profile), wakeup_local LOCAL3, wakeup_cyclic_ms 5
    CHECK(CONFIG.wakeup.sources == (wakeup::canBus(0U) | wakeup::local(3U) | wakeup::TIMER));
    CHECK(CONFIG.wakeup.cyclicMs == 5U);
    CHECK(NX_ECU_STATE_WAKEUP_SOURCES == 0x00080110U);
    CHECK(NX_ECU_STATE_VERIFY == 1);
}

void behaviourWithProfile()
{
    using Action = EcuStateMachine::Action;
    EcuStateMachine m(CONFIG);
    m.runLevelReached(1000U, wakeup::WATCHDOG);
    CHECK(m.getState() == State::RUN);
    CHECK(m.cyclic(1000U, false, true, 0U) == Action::NONE); // forced sleep, min run 0
    CHECK(m.getState() == State::STANDBY);
    CHECK(m.cyclic(1749U, false, true, 0U) == Action::NONE);
    // post-run over: the run-down starts, both steps without provider
    CHECK(m.cyclic(1750U, false, true, 0U) == Action::RUN_DOWN_STEP);
    CHECK(m.getState() == State::RUNDOWN);
    CHECK(m.getShutdownStep() == ShutdownStep::NVM);
    CHECK(m.getShutdownStepTimeoutMs() == 10U);
    CHECK(m.shutdownStepResult(StepState::NOT_PRESENT, 1750U) == Action::NONE);
    CHECK(m.getShutdownStep() == ShutdownStep::CAN_STOP);
    CHECK(m.getShutdownStepTimeoutMs() == 20U);
    CHECK(m.shutdownStepResult(StepState::DONE, 1760U) == Action::NONE);
    // SYS-174: the safe outputs step last, with the fixed limit of the mechanism
    CHECK(m.getShutdownStep() == ShutdownStep::SAFE_OUTPUTS);
    CHECK(m.getShutdownStepTimeoutMs() == SAFE_OUTPUTS_STEP_TIMEOUT_MS);
    CHECK(m.cyclic(1770U, false, true, 0U) == Action::RUN_DOWN_STEP);
    CHECK(m.shutdownStepResult(StepState::NOT_PRESENT, 1770U) == Action::SHUTDOWN);
    CHECK(m.cyclic(1800U, false, true, wakeup::canBus(3U)) == Action::NONE);
    CHECK(m.shutdownLevelReached(1810U) == Action::POWER_DOWN); // wake-up during shutdown: sleep anyway
    CHECK(m.getState() == State::SLEEP);
    // SYS-09: the sleep timeout counts from the power down request, not from entering SLEEP (output flush)
    CHECK(m.cyclic(2000U, false, true, 0U) == Action::NONE);
    CHECK(m.powerDownResult(IPowerSupply::PowerDownResult::STARTED, 2000U) == Action::NONE);
    CHECK(m.cyclic(2100U, false, true, 0U) == Action::NONE);
    CHECK(m.cyclic(2101U, false, true, 0U) == Action::RESTART);
    CHECK(m.getRestartReason() == EcuStateMachine::RestartReason::SLEEP_TIMEOUT);
}

/**
 * step_error continue of the profile (a project without NvM step: tools/rtegen refuses continue with one, SYS-174):
 * a failed CAN step does not stop the run-down; a failed NvM step would still restart (isContinuableStep()).
 */
void stepErrorContinueWithProfile()
{
    using Action = EcuStateMachine::Action;
    {
        EcuStateMachine m(CONFIG);
        m.runLevelReached(0U, wakeup::WATCHDOG);
        CHECK(m.cyclic(0U, false, true, 0U) == Action::NONE);
        CHECK(m.cyclic(750U, false, true, 0U) == Action::RUN_DOWN_STEP);
        CHECK(m.shutdownStepResult(StepState::NOT_PRESENT, 750U) == Action::NONE);
        CHECK(m.cyclic(760U, false, true, 0U) == Action::RUN_DOWN_STEP);
        CHECK(m.getShutdownStep() == ShutdownStep::CAN_STOP);
        CHECK(m.shutdownStepResult(StepState::FAILED, 760U) == Action::NONE);
        CHECK(m.getState() == State::RUNDOWN);
        CHECK(m.getStepState(ShutdownStep::CAN_STOP) == StepState::FAILED);
        CHECK(m.getShutdownStep() == ShutdownStep::SAFE_OUTPUTS);
        CHECK(m.cyclic(770U, false, true, 0U) == Action::RUN_DOWN_STEP);
        CHECK(m.shutdownStepResult(StepState::DONE, 770U) == Action::SHUTDOWN);
        CHECK(!m.isRestartIssued());
        CHECK(m.getStepAbortState() == StepState::FAILED);
        CHECK(m.getCounters().stepFailed == 1U);
    }
    {
        EcuStateMachine m(CONFIG);
        m.runLevelReached(0U, wakeup::WATCHDOG);
        CHECK(m.cyclic(0U, false, true, 0U) == Action::NONE);
        CHECK(m.cyclic(750U, false, true, 0U) == Action::RUN_DOWN_STEP);
        CHECK(m.shutdownStepResult(StepState::FAILED, 750U) == Action::RESTART);
        CHECK(m.getRestartReason() == EcuStateMachine::RestartReason::RUN_DOWN_STEP_FAILED);
        CHECK(m.getStepState(ShutdownStep::CAN_STOP) == StepState::SKIPPED);
    }
}

} // namespace

int main()
{
    generatedValues();
    std::printf("%s generatedValues\n", (failures == 0) ? "ok  " : "FAIL");
    int before = failures;
    behaviourWithProfile();
    std::printf("%s behaviourWithProfile\n", (failures == before) ? "ok  " : "FAIL");
    before = failures;
    stepErrorContinueWithProfile();
    std::printf("%s stepErrorContinueWithProfile\n", (failures == before) ? "ok  " : "FAIL");
    std::printf("%d checks, %d failures\n", checks, failures);
    return (failures == 0) ? 0 : 1;
}
